{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js"
  }
}
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { DatabaseSync } from 'node:sqlite';

const root = dirname(fileURLToPath(import.meta.url));
const port = Number.parseInt(process.env.PORT || '8080', 10);
const dbPath = process.env.DB_PATH || join(root, 'workboard.sqlite');
const db = new DatabaseSync(dbPath);
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
)`);
db.exec(`CREATE TABLE IF NOT EXISTS tasks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
)`);

function send(res, status, body, contentType = 'application/json; charset=utf-8') {
  res.writeHead(status, { 'content-type': contentType, 'cache-control': 'no-store' });
  res.end(body);
}

async function readBody(req) {
  let raw = '';
  for await (const chunk of req) raw += chunk;
  try { return JSON.parse(raw); } catch { return null; }
}

const server = createServer(async (req, res) => {
  const url = new URL(req.url, 'http://localhost');
  if (req.method === 'GET' && url.pathname === '/health') {
    return send(res, 200, JSON.stringify({ status: 'ok' }));
  }
  if (req.method === 'GET' && url.pathname === '/api/projects') {
    const projects = db.prepare('SELECT id, name FROM projects ORDER BY id ASC').all();
    return send(res, 200, JSON.stringify(projects));
  }
  if (req.method === 'POST' && url.pathname === '/api/projects') {
    const body = await readBody(req);
    const name = typeof body?.name === 'string' ? body.name.trim() : '';
    if (!name) return send(res, 400, JSON.stringify({ error: 'Project name is required' }));
    const result = db.prepare('INSERT INTO projects (name) VALUES (?)').run(name);
    return send(res, 201, JSON.stringify({ id: Number(result.lastInsertRowid), name }));
  }
  const projectMatch = url.pathname.match(/^\/api\/projects\/(\d+)$/);
  const tasksMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks$/);
  if (tasksMatch) {
    const projectId = Number(tasksMatch[1]);
    const exists = db.prepare('SELECT id FROM projects WHERE id = ?').get(projectId);
    if (!exists) return send(res, 404, JSON.stringify({ error: 'Project not found' }));
    if (req.method === 'GET') {
      const tasks = db.prepare('SELECT id, project_id AS projectId, title, completed FROM tasks WHERE project_id = ? ORDER BY id ASC').all(projectId);
      return send(res, 200, JSON.stringify(tasks.map((task) => ({ ...task, completed: Boolean(task.completed) }))));
    }
    if (req.method === 'POST') {
      const body = await readBody(req);
      const title = typeof body?.title === 'string' ? body.title.trim() : '';
      if (!title) return send(res, 400, JSON.stringify({ error: 'Task title is required' }));
      const result = db.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)').run(projectId, title);
      return send(res, 201, JSON.stringify({ id: Number(result.lastInsertRowid), projectId, title, completed: false }));
    }
  }
  const taskMatch = url.pathname.match(/^\/api\/tasks\/(\d+)$/);
  if (req.method === 'PATCH' && taskMatch) {
    const body = await readBody(req);
    if (typeof body?.completed !== 'boolean') return send(res, 400, JSON.stringify({ error: 'Invalid completion state' }));
    const result = db.prepare('UPDATE tasks SET completed = ? WHERE id = ?').run(body.completed ? 1 : 0, Number(taskMatch[1]));
    if (!result.changes) return send(res, 404, JSON.stringify({ error: 'Task not found' }));
    return send(res, 200, JSON.stringify({ ok: true }));
  }
  if (req.method === 'GET' && projectMatch) {
    const project = db.prepare('SELECT id, name FROM projects WHERE id = ?').get(Number(projectMatch[1]));
    if (!project) return send(res, 404, JSON.stringify({ error: 'Project not found' }));
    return send(res, 200, JSON.stringify(project));
  }
  if (req.method === 'GET' && (url.pathname === '/' || /^\/projects\/\d+\/?$/.test(url.pathname))) {
    try {
      const html = await readFile(join(root, 'index.html'));
      return send(res, 200, html, 'text/html; charset=utf-8');
    } catch {
      return send(res, 500, 'Application unavailable', 'text/plain; charset=utf-8');
    }
  }
  return send(res, 404, JSON.stringify({ error: 'Not found' }));
});

server.listen(port, '0.0.0.0');
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Workboard</title>
  <style>
    :root { color-scheme: light; font-family: system-ui, sans-serif; color: #172033; background: #f5f7fb; }
    * { box-sizing: border-box; }
    body { margin: 0; }
    main { width: min(720px, calc(100% - 40px)); margin: 64px auto; }
    h1 { margin: 0 0 28px; font-size: 2rem; }
    form { display: flex; gap: 10px; align-items: end; margin-bottom: 24px; }
    label { display: block; font-weight: 600; margin-bottom: 7px; }
    .field { flex: 1; }
    input { width: 100%; border: 1px solid #aab4c5; border-radius: 6px; padding: 11px 12px; font: inherit; background: white; }
    button { border: 0; border-radius: 6px; padding: 11px 16px; font: inherit; font-weight: 600; cursor: pointer; background: #2458c6; color: white; }
    button:hover { background: #1948a8; }
    .project-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 14px 16px; background: white; border: 1px solid #dce2ec; border-radius: 7px; margin: 10px 0; }
    .project-name { overflow-wrap: anywhere; }
    .alert { color: #a32323; margin: -12px 0 18px; }
    .task-row { display: flex; align-items: center; gap: 12px; padding: 12px 16px; background: white; border: 1px solid #dce2ec; border-radius: 7px; margin: 10px 0; }
    .task-row input { width: auto; }
    select { width: 100%; border: 1px solid #aab4c5; border-radius: 6px; padding: 11px 12px; font: inherit; background: white; }
    [hidden] { display: none !important; }
    @media (max-width: 520px) { main { margin-top: 36px; } form { align-items: stretch; flex-direction: column; } }
  </style>
</head>
<body>
  <main id="app" aria-live="polite"></main>
  <script type="module">
    const app = document.querySelector('#app');
    const esc = (value) => String(value).replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);

    async function renderList() {
      const response = await fetch('/api/projects');
      const projects = await response.json();
      app.innerHTML = `<h1>Workboard</h1>
        <form id="create-form">
          <div class="field"><label for="project-name">Project name</label><input id="project-name" name="name" type="text" autocomplete="off"></div>
          <button type="submit">Create project</button>
        </form>
        <p class="alert" id="project-alert" role="alert" hidden></p>
        <section aria-label="Projects" id="project-list"></section>`;
      const list = app.querySelector('#project-list');
      list.innerHTML = projects.map((project) => `<div class="project-row" data-testid="project-row">
        <span class="project-name">${esc(project.name)}</span>
        <button type="button" data-project-id="${project.id}">Open project</button>
      </div>`).join('');
      app.querySelector('#create-form').addEventListener('submit', async (event) => {
        event.preventDefault();
        const input = app.querySelector('#project-name');
        const alert = app.querySelector('#project-alert');
        const name = input.value.trim();
        if (!name) { alert.textContent = 'Project name is required'; alert.hidden = false; input.focus(); return; }
        const created = await fetch('/api/projects', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ name }) });
        if (!created.ok) { alert.textContent = 'Project name is required'; alert.hidden = false; return; }
        history.pushState({}, '', '/');
        await renderList();
      });
      list.addEventListener('click', (event) => {
        const button = event.target.closest('button[data-project-id]');
        if (button) navigate(`/projects/${button.dataset.projectId}`);
      });
    }

    async function renderProject(id) {
      const response = await fetch(`/api/projects/${encodeURIComponent(id)}`);
      if (!response.ok) { history.replaceState({}, '', '/'); return renderList(); }
      const project = await response.json();
      app.innerHTML = `<button id="back" type="button">Projects</button><h1>${esc(project.name)}</h1>
        <form id="task-form"><div class="field"><label for="task-title">Task title</label><input id="task-title" name="title" type="text" autocomplete="off"></div><button type="submit">Create task</button></form>
        <p class="alert" id="task-alert" role="alert" hidden></p>
        <div class="field"><label for="task-filter">Task filter</label><select id="task-filter"><option>All</option><option>Open</option><option>Completed</option></select></div>
        <section aria-label="Tasks" id="task-list"></section>`;
      app.querySelector('#back').addEventListener('click', () => navigate('/'));
      const list = app.querySelector('#task-list');
      const filter = app.querySelector('#task-filter');
      let tasks = await (await fetch(`/api/projects/${encodeURIComponent(id)}/tasks`)).json();
      const showTasks = () => {
        const mode = filter.value;
        list.innerHTML = tasks.filter((task) => mode === 'All' || (mode === 'Open' ? !task.completed : task.completed)).map((task) => `<div class="task-row" data-testid="task-row"><input type="checkbox" data-task-id="${task.id}" aria-label="Complete ${esc(task.title)}" ${task.completed ? 'checked' : ''}><span>${esc(task.title)}</span></div>`).join('');
      };
      filter.addEventListener('change', showTasks);
      showTasks();
      app.querySelector('#task-form').addEventListener('submit', async (event) => {
        event.preventDefault();
        const input = app.querySelector('#task-title');
        const alert = app.querySelector('#task-alert');
        const title = input.value.trim();
        if (!title) { alert.textContent = 'Task title is required'; alert.hidden = false; input.focus(); return; }
        const response = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ title }) });
        if (!response.ok) { alert.textContent = 'Task title is required'; alert.hidden = false; return; }
        tasks.push(await response.json()); input.value = ''; alert.hidden = true; showTasks();
      });
      list.addEventListener('change', async (event) => {
        const checkbox = event.target.closest('input[data-task-id]');
        if (!checkbox) return;
        await fetch(`/api/tasks/${checkbox.dataset.taskId}`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ completed: checkbox.checked }) });
        const task = tasks.find((item) => item.id === Number(checkbox.dataset.taskId));
        if (task) task.completed = checkbox.checked;
        showTasks();
      });
    }

    function navigate(path) {
      history.pushState({}, '', path);
      renderRoute();
    }
    function renderRoute() {
      const match = location.pathname.match(/^\/projects\/(\d+)\/?$/);
      return match ? renderProject(match[1]) : renderList();
    }
    window.addEventListener('popstate', renderRoute);
    renderRoute();
  </script>
</body>
</html>
